<?php
function mka_priority_defaults(){return array('baixa'=>'#21834b','normal'=>'#1764d6','media'=>'#b77900','alta'=>'#da6800','urgente'=>'#c82740');}
function mka_priority_schema($db){$db->query("CREATE TABLE IF NOT EXISTS suite_priority_hidden (priority VARCHAR(100) NOT NULL PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->query("CREATE TABLE IF NOT EXISTS suite_priority_colors (priority VARCHAR(100) NOT NULL PRIMARY KEY,color CHAR(7) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");}
function mka_priority_colors($db){$colors=mka_priority_defaults();$q=$db->query('SELECT priority,color FROM suite_priority_colors');foreach($q->fetch_all(MYSQLI_ASSOC) as $r)$colors[$r['priority']]=$r['color'];foreach(mka_priority_hidden($db) as $name)unset($colors[$name]);return $colors;}
function mka_priority_hidden($db){return array_column($db->query("SELECT priority FROM suite_priority_hidden")->fetch_all(MYSQLI_ASSOC),"priority");}
function mka_priority_save($db,$values,$removed=array()){
 if(!is_array($removed)||count($removed)>100)throw new InvalidArgumentException("Lista de remoção inválida.");foreach($removed as $name)if(!is_string($name)||trim($name)===""||mb_strlen($name)>100)throw new InvalidArgumentException("Etiqueta inválida.");
 if(!is_array($values)||count($values)>100)throw new InvalidArgumentException('Lista de prioridades inválida.');
 $clean=array();foreach($values as $name=>$color){$name=trim((string)$name);if($name===''||mb_strlen($name)>100||!is_string($color)||!preg_match('/^#[a-f0-9]{6}$/iD',$color))throw new InvalidArgumentException('Informe o nome e uma cor válida para cada prioridade.');$clean[$name]=strtolower($color);}
 $db->begin_transaction();try{$hide=$db->prepare("INSERT IGNORE INTO suite_priority_hidden(priority) VALUES(?)");$delete=$db->prepare("DELETE FROM suite_priority_colors WHERE priority=?");foreach($removed as $name){$hide->bind_param("s",$name);$hide->execute();$delete->bind_param("s",$name);$delete->execute();}$restore=$db->prepare("DELETE FROM suite_priority_hidden WHERE priority=?");$q=$db->prepare('INSERT INTO suite_priority_colors(priority,color) VALUES(?,?) ON DUPLICATE KEY UPDATE color=VALUES(color)');foreach($clean as $name=>$color){$restore->bind_param('s',$name);$restore->execute();$q->bind_param('ss',$name,$color);$q->execute();}$db->commit();}catch(Throwable $e){$db->rollback();throw $e;}
}
